#!/usr/bin/env python3
from pathlib import Path
import datetime
import py_compile
import re
import sys
import tempfile

ROOT = Path.cwd().resolve()
required = [
    ROOT / "app/api/v1/endpoints/admin_api.py",
    ROOT / "app/api/v1/endpoints/reporting.py",
    ROOT / "app/services/gradebook_service.py",
    (ROOT / "../src/pages/admin/GradebookPage.tsx").resolve(),
    (ROOT / "../src/pages/admin/LabAllocation.tsx").resolve(),
    (ROOT / "../src/pages/admin/MonitoringAnalytics.tsx").resolve(),
    (ROOT / "../src/pages/admin/ReportsPage.tsx").resolve(),
]
missing = [str(path) for path in required if not path.exists()]
if missing:
    print("ERROR: Run this from ~/Cyber_Range_Lab-/backup/backend")
    for item in missing:
        print(" -", item)
    sys.exit(1)

stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")

def backup(path):
    dst = path.with_name(path.name + f".before_point7_{stamp}")
    dst.write_bytes(path.read_bytes())
    print("Backup:", dst)

def write_file(relative, content):
    path = (ROOT / relative).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup(path)
    path.write_text(content)
    print("Wrote:", path)

def replace_route_function(text, func_name, new_block):
    match = re.search(rf"(?m)^def {re.escape(func_name)}\(", text)
    if not match:
        raise RuntimeError(f"Could not find function: {func_name}")
    decorator_start = text.rfind("\n@router.", 0, match.start())
    if decorator_start == -1:
        if text.startswith("@router."):
            decorator_start = 0
        else:
            raise RuntimeError(f"Could not find decorator for: {func_name}")
    else:
        decorator_start += 1
    next_decorator = text.find("\n@router.", match.end())
    end = len(text) if next_decorator == -1 else next_decorator + 1
    return text[:decorator_start] + new_block.rstrip() + "\n\n" + text[end:]

